def minPath(grid, k):
    N = len(grid)
    visited = [[False] * N for _ in range(N)]
    min_path = []
    min_value = float('inf')

    def dfs(x, y, path):
        nonlocal min_value, min_path
        if len(path) == k:
            current_value = grid[x][y]
            if current_value < min_value:
                min_value = current_value
                min_path = path[:]
            return

        for dx, dy in [(0, 1), (1, 0), (0, -1), (-1, 0)]:
            nx, ny = x + dx, y + dy
            if 0 <= nx < N and 0 <= ny < N and not visited[nx][ny]:
                visited[nx][ny] = True
                dfs(nx, ny, path + [grid[nx][ny]])
                visited[nx][ny] = False

    for i in range(N):
        for j in range(N):
            dfs(i, j, [grid[i][j]])

    return min_path

