def do_algebra(operator, operand):
    # Ensure the lengths of the lists are as expected
    assert len(operator) == len(operand) - 1, "The length of operator list must be one less than the length of operand list."
    assert len(operand) >= 2, "Operand list must have at least two elements."
    assert all(isinstance(op, str) for op in operator), "All elements in operator list must be strings."
    assert all(isinstance(num, int) and num >= 0 for num in operand), "All elements in operand list must be non-negative integers."

    # Start with the first operand
    result = operand[0]

    # Iterate over the operators and operands, applying each operation in sequence
    for i in range(len(operator)):
        op = operator[i]
        num = operand[i + 1]

        # Perform the operation and update the result
        if op == '+':
            result += num
        elif op == '-':
            result -= num
        elif op == '*':
            result *= num
        elif op == '//':
            result //= num
        elif op == '**':
            result **= num
        else:
            raise ValueError(f"Unsupported operator: {op}")

    return result

